const adminProviderJobStats = `-- name: AdminProviderJobStats :one
SELECT
  (SELECT count(*) FROM bookings b
    WHERE b.technician_id = $1 AND b.state = 'COMPLETED')::int AS jobs_total,
  (SELECT count(*) FROM bookings b
    JOIN booking_events be ON be.booking_id = b.id AND be.to_state = 'COMPLETED'
    WHERE b.technician_id = $1
      AND be.created_at >= $2::timestamptz)::int AS completed_today,
  (SELECT count(*) FROM bookings b
    WHERE b.technician_id = $1
      AND b.state IN ('ASSIGNED', 'EN_ROUTE', 'ARRIVED', 'IN_PROGRESS', 'AWAITING_COMPLETION'))::int AS active_now,
  (SELECT COALESCE(sum(b.quoted_total_paise), 0) FROM bookings b
    JOIN booking_events be ON be.booking_id = b.id AND be.to_state = 'COMPLETED'
    WHERE b.technician_id = $1
      AND be.created_at >= $2::timestamptz)::bigint AS earnings_today,
  (SELECT COALESCE(sum(b.quoted_total_paise), 0) FROM bookings b
    JOIN booking_events be ON be.booking_id = b.id AND be.to_state = 'COMPLETED'
    WHERE b.technician_id = $1
      AND be.created_at >= $3::timestamptz)::bigint AS cycle_revenue
`

