const adminProviderPerformanceBuckets = `-- name: AdminProviderPerformanceBuckets :many
SELECT
  width_bucket(
    EXTRACT(EPOCH FROM b.created_at),
    EXTRACT(EPOCH FROM $1::timestamptz),
    EXTRACT(EPOCH FROM $2::timestamptz), 8
  )::int AS bucket,
  count(*)::int AS assigned,
  count(*) FILTER (WHERE b.state = 'COMPLETED')::int AS completed,
  count(*) FILTER (WHERE b.state IN ('CANCELLED', 'FAILED'))::int AS cancelled,
  count(*) FILTER (WHERE b.state IN ('COMPLETED', 'CANCELLED', 'FAILED'))::int AS terminal,
  count(*) FILTER (WHERE EXISTS (
    SELECT 1 FROM booking_events be
    WHERE be.booking_id = b.id AND be.to_state = 'ESCALATED'))::int AS escalated
FROM bookings b
WHERE b.technician_id = $3
  AND b.created_at >= $1::timestamptz AND b.created_at < $2::timestamptz
GROUP BY 1
`

type AdminProviderPerformanceBucketsParams struct {
	FromTime     pgtype.Timestamptz
	ToTime       pgtype.Timestamptz
	TechnicianID *uuid.UUID
}

type AdminProviderPerformanceBucketsRow struct {
	Bucket    int32
	Assigned  int32
	Completed int32
	Cancelled int32
	Terminal  int32
	Escalated int32
}

// The 90-day performance trend in 8 equal buckets (by booking creation): jobs assigned,
// completions, cancellations/failures, terminal outcomes and escalations.
func (q *Queries) AdminProviderPerformanceBuckets(ctx context.Context, arg AdminProviderPerformanceBucketsParams) ([]AdminProviderPerformanceBucketsRow, error) {
	rows, err := q.db.Query(ctx, adminProviderPerformanceBuckets, arg.FromTime, arg.ToTime, arg.TechnicianID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AdminProviderPerformanceBucketsRow{}
	for rows.Next() {
		var i AdminProviderPerformanceBucketsRow
		if err := rows.Scan(
			&i.Bucket,
			&i.Assigned,
			&i.Completed,
			&i.Cancelled,
			&i.Terminal,
			&i.Escalated,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

