const adminZoneOnlineCounts = `-- name: AdminZoneOnlineCounts :many
WITH derived AS (
  SELECT
    t.city AS zone,
    CASE
      WHEN st.standing = 'BLOCKED' THEN 'offboarded'
      WHEN st.standing = 'SUSPENDED' AND st.suspended_until > now() THEN 'suspended'
      WHEN EXISTS (SELECT 1 FROM bookings b
                    WHERE b.technician_id = t.user_id
                      AND b.state IN ('ASSIGNED', 'EN_ROUTE', 'ARRIVED', 'IN_PROGRESS', 'AWAITING_COMPLETION'))
        THEN 'on_job'
      WHEN t.is_online AND NOT t.on_leave
           AND GREATEST(t.updated_at, COALESCE(t.last_location_at, t.updated_at))
               > now() - make_interval(secs => $1::int)
        THEN 'free'
      ELSE 'offline'
    END::text AS status
  FROM technicians t
  JOIN users u ON u.id = t.user_id
  LEFT JOIN provider_admin_states st ON st.technician_id = t.user_id
  WHERE u.deleted_at IS NULL
)
SELECT d.zone, count(*) FILTER (WHERE d.status IN ('free', 'on_job'))::int AS online_count
FROM derived d
GROUP BY d.zone
ORDER BY d.zone
`

type AdminZoneOnlineCountsRow struct {
	Zone        string
	OnlineCount int32
}

// Online (free or on-job) providers per zone — the roster's supply-health strip.
func (q *Queries) AdminZoneOnlineCounts(ctx context.Context, staleAfterSeconds int32) ([]AdminZoneOnlineCountsRow, error) {
	rows, err := q.db.Query(ctx, adminZoneOnlineCounts, staleAfterSeconds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AdminZoneOnlineCountsRow{}
	for rows.Next() {
		var i AdminZoneOnlineCountsRow
		if err := rows.Scan(&i.Zone, &i.OnlineCount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const bumpProviderStandingVersion = `-- name: BumpProviderStandingVersion :one
INSERT INTO provider_admin_states AS pas (technician_id)
VALUES ($1)
ON CONFLICT (technician_id) DO UPDATE
   SET updated_at = now(),
       version    = pas.version + 1
 WHERE pas.version = $2
RETURNING version
`

type BumpProviderStandingVersionParams struct {
	TechnicianID    uuid.UUID
	ExpectedVersion int64
}

// Force-offline changes availability (identity's aggregate), not standing — but it still
// consumes the provider's concurrency token, so two admins acting on a stale profile still
// collide. Inserts the implicit ACTIVE row on first touch.
func (q *Queries) BumpProviderStandingVersion(ctx context.Context, arg BumpProviderStandingVersionParams) (int64, error) {
	row := q.db.QueryRow(ctx, bumpProviderStandingVersion, arg.TechnicianID, arg.ExpectedVersion)
	var version int64
	err := row.Scan(&version)
	return version, err
}

const decideApplication = `-- name: DecideApplication :one
UPDATE provider_applications
   SET status                 = $1,
       decided_at             = now(),
       decided_by             = $2,
       decision_reason_code   = $3,
       decision_note          = $4,
       approved_technician_id = $5,
       updated_at             = now(),
       version                = version + 1
 WHERE id = $6
   AND version = $7
   AND status IN ('pending', 'awaiting_docs')
RETURNING version
`

type DecideApplicationParams struct {
	Status               string
	DecidedBy            *uuid.UUID
	DecisionReasonCode   *string
	DecisionNote         string
	ApprovedTechnicianID *uuid.UUID
	ApplicationID        uuid.UUID
	ExpectedVersion      int64
}

// THE COMPARE-AND-SWAP for a decision, doubly guarded: the version must match AND the
// application must still be undecided (a decision is terminal — approved/rejected rows can
// never be decided again, whatever version a caller replays).
func (q *Queries) DecideApplication(ctx context.Context, arg DecideApplicationParams) (int64, error) {
	row := q.db.QueryRow(ctx, decideApplication,
		arg.Status,
		arg.DecidedBy,
		arg.DecisionReasonCode,
		arg.DecisionNote,
		arg.ApprovedTechnicianID,
		arg.ApplicationID,
		arg.ExpectedVersion,
	)
	var version int64
	err := row.Scan(&version)
	return version, err
}

