const upsertProviderStanding = `-- name: UpsertProviderStanding :one
INSERT INTO provider_admin_states AS pas
    (technician_id, standing, reason_code, note, suspended_until, decided_by, decided_at)
VALUES ($1, $2, $3, $4,
        $5, $6, now())
ON CONFLICT (technician_id) DO UPDATE
   SET standing        = EXCLUDED.standing,
       reason_code     = EXCLUDED.reason_code,
       note            = EXCLUDED.note,
       suspended_until = EXCLUDED.suspended_until,
       decided_by      = EXCLUDED.decided_by,
       decided_at      = now(),
       updated_at      = now(),
       version         = pas.version + 1
 WHERE pas.version = $7
RETURNING version
`

type UpsertProviderStandingParams struct {
	TechnicianID    uuid.UUID
	Standing        string
	ReasonCode      *string
	Note            string
	SuspendedUntil  pgtype.Timestamptz
	DecidedBy       *uuid.UUID
	ExpectedVersion int64
}

// THE COMPARE-AND-SWAP for a standing change. A first-ever write inserts at version 1 (the
// service has already verified the expected version was 0, inside the same transaction); a
// later write only lands when the version still matches — zero rows means another admin got
// there first, which the service turns into the 409 the console renders.
func (q *Queries) UpsertProviderStanding(ctx context.Context, arg UpsertProviderStandingParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertProviderStanding,
		arg.TechnicianID,
		arg.Standing,
		arg.ReasonCode,
		arg.Note,
		arg.SuspendedUntil,
		arg.DecidedBy,
		arg.ExpectedVersion,
	)
	var version int64
	err := row.Scan(&version)
	return version, err
}
